public Transform ClosestPlaceToPlayer(Transform[] places) {
  var playerPos = Instance.transform.position;
  float closestDistance = float.MaxValue;
  Transform closestPlace = null;
  foreach (Transform place in places) {
    var distance = Vector3.Distance(playerPos, place.position);
    if (distance < closestDistance) { closestDistance = distance; closestPlace = place; }
  }
  return closestPlace;
}
```

