    case BeastManager.State.RoamingOnTarget:
      beastStateIndicator.rectTransform.DOScale(0.6f, 0.5f);
      beastStateIndicator.DOColor(orangeColor, 0.5f);
      break;

    default:
      canvas.gameObject.SetActive(false);
      break;
  }
}
