        //subscribing (listening) to some events
        LevelEventHub.OnPowerSwitchActivated += OnPowerSwitchActivated;
    }

    private void OnDisable() {
        //unsubscribing to some events
        LevelEventHub.OnPowerSwitchActivated -= OnPowerSwitchActivated;
    }
